static U mpow(U a,U e,U n){U x=1;while(e){if(e&1)x=W(x)*a%n;a=W(a)*a%n;e>>=1;}return x;}
static bool reference(U n){if(n<2)return false;if(!(n&1))return n==2;U d=n-1;unsigned s=std::countr_zero(d);d>>=s;for(U a:std::array<U,7>{2,325,9375,28178,450775,9780504,1795265022}){a%=n;if(!a)continue;U x=mpow(a,d,n);if(x==1||x==n-1)continue;unsigned j=1;for(;j<s;++j){x=W(x)*x%n;if(x==n-1)break;}if(j==s)return false;}return true;}
template<bool Relaxed>static void powers(U n,std::mt19937_64& rng){reinsirk::detail::MillerRabin64<Relaxed> c(n);U R=(W(1)<<64)%n;for(U e:std::array<U,9>{0,1,2,3,63,64,U(1)<<63,(U(1)<<63)-1,~U(0)}){U a=rng()%n;U mont=W(a)*R%n;for(unsigned alt=0;alt<(Relaxed?2u:1u);++alt){U b=mont+(alt?n:0);U got=c.power(b,e);need(got<(Relaxed?2*n:n));need(c.normalize(got)==W(mpow(a,e,n))*R%n);}}}
int main(){std::mt19937_64 rng(412875);std::vector<U> ns{3,5,17,4294967291ULL,4759123141ULL,(U(1)<<62)-1,(U(1)<<62)+1,(U(1)<<63)-1,(U(1)<<63)+1,~U(0)-2,~U(0)};for(unsigned i=0;i<200;++i)ns.push_back(rng()|1);for(U n:ns){powers<false>(n,rng);if(n<(U(1)<<62))powers<true>(n,rng);need(is_prime(n)==reference(n));if(n>=4759123141ULL){bool v=n<(U(1)<<62)?reinsirk::detail::MillerRabin64<true>(n).test_deterministic():reinsirk::detail::MillerRabin64<false>(n).test_deterministic();need(v==reference(n));}}std::printf("PASS checks=%zu moduli=%zu\n",checks,ns.size());}

