static bool witness(U n,U a){U d=n-1;unsigned s=std::countr_zero(d);d>>=s;U x=mpow(a,d,n);if(x==1||x==n-1)return true;for(unsigned j=1;j<s;++j){x=W(x)*x%n;if(x==n-1)return true;}return false;}
